import{_ as l,a0 as p,w as r,s as u,ao as i,I as a,x as e,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用 Linux 终端浏览你的计算机 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 终端浏览你的计算机 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 终端浏览你的计算机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 终端浏览你的计算机 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210803 Use the Linux terminal to navigate throughout your computer","title":"使用 Linux 终端浏览你的计算机","tag":"202108","desc":""},"relativePath":"202108/20210803 Use the Linux terminal to navigate throughout your computer.md","filePath":"[post].md"}'),d={name:"202108/20210803 Use the Linux terminal to navigate throughout your computer.md"};function m(x,t,T,g,f,b){const n=p("Link");return r(),u("div",null,[t[24]||(t[24]=i('<h1 id="使用-linux-终端浏览你的计算机" tabindex="-1">使用 Linux 终端浏览你的计算机 <a class="header-anchor" href="#使用-linux-终端浏览你的计算机" aria-label="Permalink to “使用 Linux 终端浏览你的计算机”">​</a></h1><blockquote><p>学习在 Linux 终端中从一个目录切换到另一个目录。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/12/113605d3hp448xm8m18wzw.jpg" alt=""></p><p>要在图形界面中浏览你的计算机上的文件夹，你可能习惯于打开一个窗口来“进入”你的计算机，然后双击一个文件夹，再双击一个子文件夹，如此反复。你也可以使用箭头按钮或按键来回溯。</p><p>而要在终端中浏览你的计算机，你可以利用 <code>cd</code> 命令。你可以使用 <code>cd ..</code> 回到 <em>上一级</em> 目录，或者使用 <code>cd ./另一个/文件夹的/路径</code> 来跳过许多文件夹进入一个特定的位置。</p>',5)),a("p",null,[t[1]||(t[1]=e("你在互联网上已经使用的 URL 的概念，实际上直接来自 ",-1)),s(n,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:o(()=>[...t[0]||(t[0]=[e("POSIX",-1)])]),_:1}),t[2]||(t[2]=e("。当你浏览某个网站的一个特定页面时，比如 ",-1)),t[3]||(t[3]=a("code",null,"http://www.example.com/tutorials/lesson2.html",-1)),t[4]||(t[4]=e("，你实际上做的是进入 ",-1)),t[5]||(t[5]=a("code",null,"/var/www/imaginarysite/tutorials/",-1)),t[6]||(t[6]=e(" 目录，并打开一个叫 ",-1)),t[7]||(t[7]=a("code",null,"classic2.html",-1)),t[8]||(t[8]=e(" 的文件。当然，你是在 Web 浏览器中打开它的，浏览器会将所有那些看起来奇怪的 HTML 代码解释成漂亮的文本和图片。但这两者的思路是完全一样的。",-1))]),t[25]||(t[25]=i(`<p>如果你把你的计算机看成是互联网（或者把互联网看成是计算机会更合适），那么你就能理解如何在你的文件夹和文件中遨游了。如果从你的用户文件夹（你的家目录，或简记为 <code>~</code>）开始，那么你想切换到的文件夹都是相对于这个文件夹而言的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/Documents</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux/Documents</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cd ..</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux</span></span></code></pre></div><p>这需要一些练习，但一段时间后，它会变得比你打开和关闭窗口、点击返回按钮和文件夹图标快得多。</p><h3 id="用-tab-键自动补全" tabindex="-1">用 Tab 键自动补全 <a class="header-anchor" href="#用-tab-键自动补全" aria-label="Permalink to “用 Tab 键自动补全”">​</a></h3><p>键盘上的 <code>Tab</code> 键可以自动补全你开始输入的文件夹和文件的名字。如果你要 <code>cd</code> 到 <code>~/Documents</code> 文件夹，那么你只需要输入 <code>cd ~/Doc</code>，然后按 <code>Tab</code> 键即可。你的 Shell 会自动补全 <code>uments</code>。这不仅仅是一个令人愉快的便利工具，它也是一种防止错误的方法。如果你按下 <code>Tab</code> 键而没有任何东西自动补全，那么可能你 <em>认为</em> 存在于某个位置的文件或文件件实际上并不存在。即使有经验的 Linux 用户也会试图切换到一个当前目录下不存在的文件夹，所以你可以经常使用 <code>pwd</code> 和 <code>ls</code> 命令来确认你确实在你认为你在的目录、以及你的当前目录确实包含了你认为它包含的文件。</p><hr>`,6)),a("p",null,[t[10]||(t[10]=e("via: ",-1)),s(n,{href:"https://opensource.com/article/21/8/navigate-linux-directories"},{default:o(()=>[...t[9]||(t[9]=[e("https://opensource.com/article/21/8/navigate-linux-directories",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("作者：",-1)),s(n,{href:"https://opensource.com/users/seth"},{default:o(()=>[...t[11]||(t[11]=[e("Seth Kenlon",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),s(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),s(n,{href:"https://github.com/piaoshi"},{default:o(()=>[...t[13]||(t[13]=[e("piaoshi",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[21]||(t[21]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),s(n,{href:"https://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const k=l(d,[["render",m]]);export{C as __pageData,k as default};
